'use strict';
const DATA=window.HEATSHIELD_DATA;
const PHOTOS=window.HEATSHIELD_PHOTOS||{assets:{},matched:{},references:{}};
const CITY_NAMES={get phoenix(){return tr("凤凰城")},get nyc(){return tr("纽约")},get houston(){return tr("休斯敦")},get las_vegas(){return tr("拉斯维加斯")},get miami(){return tr("迈阿密")}};
const ROUTES=['home','map','resources','alerts','profile','community','facility','forecast','analysis','compare','subscriptions','favorites','settings','about','brand','dispatch','task','welcome','choose'];
const KEY=new URLSearchParams(location.search).has('qa')?'heatshield.app.v3.qa':'heatshield.app.v3';
let persisted={};try{persisted=JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{}
const S={language:window.HeatShieldI18n.getLanguage(),page:'home',depth:0,city:DATA.cities.some(c=>c.id===persisted.city)?persisted.city:'phoenix',theme:['light','dark'].includes(persisted.theme)?persisted.theme:'light',motion:persisted.motion!==false,query:'',welcomed:persisted.welcomed===true,followed:Array.isArray(persisted.followed)?persisted.followed.filter(x=>typeof x==='string'):[],favorites:Array.isArray(persisted.favorites)?persisted.favorites.filter(x=>typeof x==='string'):[],notifications:persisted.notifications!==false,hood:0,facility:0,layer:'risk',horizon:24,cooling:true,filter:'all',tab:'community',analysis:'social',loading:false,mapExplore:false,modal:null,modalScroll:0,manager:false,units:3,plan:false,taskStatus:'draft',busy:false,read:false};
let loadToken=0,toastTimer,modalTrigger=null,renderedPage=null,modalCloseTimer,photosPrepared=false;
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,cls='')=>`<i data-lucide="${name}" class="${cls}" aria-hidden="true"></i>`;
function icons(){window.lucide?.createIcons({attrs:{'stroke-width':1.7}});document.querySelectorAll('.chips').forEach(list=>{const selected=list.querySelector('[aria-pressed="true"],.selected');if(!selected)return;const item=selected.getBoundingClientRect(),box=list.getBoundingClientRect();if(item.right>box.right)list.scrollLeft+=item.right-box.right+2;else if(item.left<box.left)list.scrollLeft-=box.left-item.left+2})}
function save(){try{localStorage.setItem(KEY,JSON.stringify({language:S.language,city:S.city,theme:S.theme,motion:S.motion,welcomed:S.welcomed,followed:S.followed,favorites:S.favorites,notifications:S.notifications}))}catch{}}
function formatHours(hours){
  if(S.language!=='en')return String(hours).replace('-', '–');
  return String(hours).replace(/(\d{2}):(\d{2})/g,(_,h,m)=>new Intl.DateTimeFormat('en-US',{hour:'numeric',minute:'2-digit',timeZone:'UTC'}).format(new Date(Date.UTC(2000,0,1,Number(h),Number(m))))).replace('-', '–');
}
function city(){return DATA.cities.find(c=>c.id===S.city)}
function risk(n){return Math.round(Math.max(0,Math.min(100,(.2*Math.max(0,Math.min(1,(80000-n.median_income)/60000))+.15*n.pct_over_65/.2+.25*(1-n.pct_tree_canopy)+.2*(1-n.pct_ac_access)+.2*n.hvi/5)*100)))}
function neighborhoods(){return DATA.neighborhoods.filter(n=>n.city===S.city).map((n,i)=>({...n,idx:i,risk:risk(n)}))}
function facilities(){return DATA.cooling_centers.filter(c=>c.city===S.city).map((c,i)=>({...c,idx:i}))}
function hood(){return neighborhoods()[S.hood]||neighborhoods()[0]}
function facility(){return facilities()[S.facility]||facilities()[0]}
const fmt=n=>Number(n).toLocaleString('en-US');
function riskLevel(v){return v>=75?['extreme',tr("极高风险")]:v>=50?['high',tr("高风险")]:v>=25?['moderate',tr("中风险")]:['low',tr("低风险")]}
function badge(v){const [c,label]=riskLevel(v);return `<span class="pill risk ${c}">${label}</span>`}
function temp(h=24){return (city().avg_summer_high_c+(h===48?.8:h===72?-.5:0)).toFixed(1)}
function followKey(n=hood()){return n.city+'|'+n.name}
function favoriteKey(c=facility()){return c.city+'|'+c.name}
function distance(a,b){const r=x=>x*Math.PI/180,z=Math.sin(r(b.lat-a.lat)/2)**2+Math.cos(r(a.lat))*Math.cos(r(b.lat))*Math.sin(r(b.lon-a.lon)/2)**2;return 6371*2*Math.asin(Math.sqrt(z))}
function nearby(){return facilities().map(c=>({...c,distance:distance(hood(),c)})).sort((a,b)=>a.distance-b.distance)}
function btn(t,action,cls='',attrs='',glyph=''){return `<button class="btn ${cls}" data-action="${action}" ${attrs}>${glyph?icon(glyph):''}<span>${t}</span></button>`}
function title(h,p='',right=''){return `<div class="page-top"><div><h1>${h}</h1>${p?`<p>${p}</p>`:''}</div>${right}</div>`}
function section(t,action=''){return `<div class="section-title"><h2>${t}</h2>${action}</div>`}
function jump(t,page){return `<button class="text-button" data-action="go" data-page="${page}">${t}${icon('arrow-up-right')}</button>`}
function back(){return `<button class="back-button" data-action="back">${tr("{p0}返回", {p0:(icon('arrow-left'))})}</button>`}
function note(t=tr("示例天气与预报 · 数据说明")){return `<button class="data-note" data-action="go" data-page="about">${icon('info')}${t}</button>`}
function row(t,sub,action='go',attrs='',glyph=''){return `<button class="list-row" data-action="${action}" ${attrs}><div class="row">${glyph?`<span class="number-circle">${icon(glyph)}</span>`:''}<span><strong>${t}</strong>${sub?`<small>${sub}</small>`:''}</span></div>${icon('chevron-right')}</button>`}
function weatherArt(){return `<img class="hero-weather" src="assets/solar-orb.svg" width="200" height="200" alt="${tr("暖金色太阳与流动的热浪")}">`}
function facilityCard(c,dist){const gallery=photoGallery(c),p=gallery.items[0];return `<button class="facility ${p?'has-photo':''}" data-action="facility" data-id="${c.idx}">${p?`<span class="facility-thumb"><img src="${p.src}" alt="" loading="lazy" decoding="async" width="76" height="88" style="object-position:${p.position}">${gallery.matched?'':`<small>${tr("参考")}</small>`}</span>`:`<span class="facility-icon">${icon(c.type==='library'?'library-big':c.type==='pool'?'waves':'landmark')}</span>`}<span class="facility-info"><span class="caption">${c.type==='library'?tr("公共图书馆"):tr("公共避暑设施")}${dist!==undefined?` ${tr("· {p0} km（直线）", {p0:(dist.toFixed(1))})}`:''}</span><h3>${esc(c.name)}</h3><span class="caption">${tr("{p0} · 标称容量 {p1} 人", {p0:(esc(formatHours(c.hours))), p1:(c.capacity)})}</span><span style="display:block"><span class="pill">${tr("开放状态待核验")}</span></span></span>${icon('chevron-right')}</button>`}
function home(){const ns=neighborhoods(),avg=Math.round(ns.reduce((s,n)=>s+n.risk,0)/ns.length),top=ns.slice().sort((a,b)=>b.risk-a.risk).slice(0,3);return `${title(tr("高温来临，提前准备"),`${tr("{p0} · {p1} 个社区", {p0:(CITY_NAMES[S.city]), p1:(ns.length)})}`, `<button class="icon-button" aria-label="${tr("刷新城市数据")}" data-action="refresh">${icon('refresh-cw')}</button>`)}<div class="home-grid"><div><section class="hero"><div class="between"><span class="label">${tr("{p0} · 高温情景", {p0:(CITY_NAMES[S.city])})}</span>${badge(avg)}</div><div class="hero-main"><div class="temperature">${temp()}<small>°C</small></div>${weatherArt()}</div><p>${tr("了解社区风险，出发前确认身边的避暑资源。")}</p><div class="hero-footer"><span>${tr("{p0}社区基线 {p1}/100", {p0:(icon('activity')), p1:(avg)})}</span><span>${tr("{p0}示例预报", {p0:(icon('clock-3'))})}</span></div>${btn(tr("查看社区风险地图"),'go','primary wide','data-page="map"','map')}</section><div class="two mt-sm"><button class="quick-action" data-action="go" data-page="resources"><span class="glyph">${icon('landmark')}</span><span><strong>${tr("寻找避暑点")}</strong><small>${tr("{p0} 处本城设施", {p0:(facilities().length)})}</small></span></button><button class="quick-action" data-action="go" data-page="subscriptions"><span class="glyph">${icon('heart-handshake')}</span><span><strong>${tr("关注我的社区")}</strong><small>${S.followed.length?`${tr("{p0} 个已关注社区", {p0:(S.followed.length)})}`:tr("添加你关心的地点")}</small></span></button></div>${section(tr("未来 72 小时"),jump(tr("详细预测"),'forecast'))}<div class="three">${[24,48,72].map(h=>`<button class="forecast-card" data-action="forecast" data-horizon="${h}"><span class="caption">${tr("+{p0} 小时", {p0:(h)})}</span>${icon(h===48?'sun':'cloud-sun')}<strong>${temp(h)}°</strong><span class="caption">${tr("示例温度")}</span></button>`).join('')}</div></div><div class="home-right">${section(tr("值得关注的社区"),jump(tr("全部社区"),'map'))}<div class="list">${top.map((n,i)=>`<button class="list-row" data-action="hood" data-id="${n.idx}"><span class="row"><span class="number-circle">0${i+1}</span><span><strong>${esc(n.name)}</strong><small>${tr("树冠 {p0}% · 空调 {p1}%", {p0:((n.pct_tree_canopy*100).toFixed(0)), p1:((n.pct_ac_access*100).toFixed(0))})}</small></span></span>${badge(n.risk)}</button>`).join('')}</div>${section(tr("本城避暑资源"),jump(tr("查看全部"),'resources'))}<div class="stack">${facilities().slice(0,2).map(c=>facilityCard(c)).join('')}</div>${section(tr("更多城市与分析"))}<div class="list">${row(tr("五城概况"),tr("比较社区与避暑设施覆盖"),'go','data-page="compare"','building-2')}${row(tr("热脆弱性分析"),tr("查看环境与人口影响因素"),'go','data-page="analysis"','chart-no-axes-combined')}</div></div></div>${note()}`}
function map(){return `${title(tr("社区风险地图"),`${tr("{p0} · {p1} 个社区", {p0:(CITY_NAMES[S.city]), p1:(neighborhoods().length)})}`)}<div id="map-controls">${mapControls()}</div>${S.layer==='3d'?window.HeatShieldRisk3D.html(CITY_NAMES[S.city]):streetMapMarkup()}<div id="map-key" class="between mt-sm">${mapKey()}</div>${section(tr("选择一个社区"))}<div class="list" id="map-community-list">${mapCommunityRows()}</div>${note(S.layer==='3d'?tr("3D 布局依据项目社区坐标 · 柱高表示风险评分"):tr("在线街道 / 本地路网快照 · 叠加点位与风险为项目记录"))}`}
function community(){const n=hood(),follow=S.followed.includes(followKey());return `${back()}${title(esc(n.name),`${tr("{p0} · 社区概况", {p0:(CITY_NAMES[S.city])})}`)}<div class="card"><div class="between"><span class="label">${tr("社区风险基线")}</span>${badge(n.risk)}</div><div class="score mt-sm">${n.risk}<small>/ 100</small></div><p class="mt-sm">${tr("人口、环境和设施可及性共同影响社区风险。")}</p></div><div class="two mt-sm"><div class="stat"><span class="caption">${tr("常住人口")}</span><strong>${fmt(n.population)}</strong></div><div class="stat"><span class="caption">${tr("HVI 指数")}</span><strong>${n.hvi}<small style="font-size:12px;color:var(--sub)"> / 5</small></strong></div></div>${section(tr("影响因素"))}<div class="card">${[[tr("树冠覆盖"),n.pct_tree_canopy*100],[tr("空调可及性"),n.pct_ac_access*100],[tr("65 岁以上人口"),n.pct_over_65*100]].map(([t,v])=>`<div class="bar-row"><div class="between"><span style="font-size:13px">${t}</span><span class="caption">${v.toFixed(0)}%</span></div><div class="track"><span style="width:${v}%"></span></div></div>`).join('')}</div>${btn(follow?tr("已关注此社区"):tr("关注此社区"),'follow','wide mt',`aria-pressed="${follow}"`,follow?'heart-handshake':'plus')}${section(tr("附近的避暑点"),jump(tr("全部设施"),'resources'))}<div class="stack">${nearby().slice(0,3).map(c=>facilityCard(c,c.distance)).join('')}</div>${btn(tr("查看未来风险"),'go','wide mt','data-page="forecast"','chart-no-axes-combined')}${note(tr("社区风险基线，非个人健康诊断 · 数据说明"))}`}
function resourceMatches(){const q=S.query.trim().toLocaleLowerCase();const aliases={library:'图书馆 library libraries',community_center:'社区中心 community center community centre',pool:'泳池 游泳池 pool swimming pool',mall:'商场 mall shopping center shopping centre'};return facilities().filter(c=>(S.filter==='all'||c.type===S.filter)&&(!q||(c.name+' '+(aliases[c.type]||'')).toLocaleLowerCase().includes(q)))}
function resourceResults(){const list=resourceMatches();return list.length?list.map(c=>facilityCard(c)).join(''):empty('search',tr("没有找到符合条件的设施"),tr("换一个名称，或清除筛选后再试。"),btn(tr("清除搜索与筛选"),'clear-filter','primary'))}
function updateResourceResults(){const list=$('#resource-results');if(!list)return;list.innerHTML=resourceResults();$('#resource-count').textContent=`${tr("{p0} 处符合条件", {p0:(resourceMatches().length)})}`;$('#clear-resource-search').hidden=!S.query;icons()}
function resources(){const types=[['all',tr("全部")],['library',tr("图书馆")],['community_center',tr("社区中心")],['pool',tr("泳池")],['mall',tr("商场")]].filter(([id])=>id==='all'||facilities().some(c=>c.type===id));return `${title(tr("找一处清凉"),`${tr("{p0} · {p1} 处避暑设施", {p0:(CITY_NAMES[S.city]), p1:(facilities().length)})}`)}<div class="resource-search"><label for="resource-search" class="sr-only">${tr("搜索设施名称或类型")}</label>${icon('search')}<input id="resource-search" type="search" placeholder="${tr("搜索图书馆、社区中心…")}" value="${esc(S.query)}" autocomplete="off" enterkeyhint="search"><button id="clear-resource-search" data-action="clear-search" aria-label="${tr("清空搜索")}" ${S.query?'':'hidden'}>${icon('x')}</button></div><div class="filter-bar"><div class="chips">${types.map(([id,t])=>`<button class="chip ${S.filter===id?'selected':''}" data-action="filter" data-value="${id}" aria-pressed="${S.filter===id}">${t}</button>`).join('')}</div><button class="icon-button" aria-label="${tr("我的收藏")}" data-action="go" data-page="favorites">${icon('bookmark')}</button></div><div class="resource-result-meta"><span id="resource-count" role="status" aria-live="polite">${tr("{p0} 处符合条件", {p0:(resourceMatches().length)})}</span><span>${tr("{p0}出发前确认开放情况", {p0:(icon('clock-3'))})}</span></div><div id="resource-results" class="facility-grid stack mt-sm">${resourceResults()}</div>${S.manager?`<div class="mt">${btn(tr("进入资源调度"),'go','wide','data-page="dispatch"','truck')}</div>`:''}${note(tr("设施开放状态与余位尚未实时接入 · 数据说明"))}`}
function photoGallery(c=facility()){const key=c.city+'|'+c.name,match=PHOTOS.matched[key];const ids=match||[PHOTOS.references[c.type]||PHOTOS.references.community_center];return {matched:!!match,items:ids.map(id=>PHOTOS.assets[id]).filter(Boolean).map(p=>({...p,caption:tr(p.caption),changes:tr(p.changes)}))}}
function facilityPhoto(c){const gallery=photoGallery(c),p=gallery.items[0];if(!p)return `<div class="big-facility">${icon('image')}</div>`;const label=gallery.matched?tr("地点实拍"):tr("场景参考");return `<figure class="facility-photo-wrap"><button class="facility-photo" data-action="facility-photos" aria-label="${tr("查看{p0}的{p1}照片及来源", {p0:(esc(c.name)), p1:(label)})}"><img src="${p.src}" alt="${esc(p.caption)}${gallery.matched?'':tr("，非该设施实拍")}" width="1000" height="660" style="object-position:${p.position}" decoding="async"><span class="facility-photo-tag">${label}</span><span class="facility-photo-count">${tr("{p0}{p1} 张", {p0:(icon('images')), p1:(gallery.items.length)})}</span></button><figcaption class="facility-photo-caption"><span>${gallery.matched?`${tr("历史实拍{p0}", {p0:(p.year?' · '+p.year:'')})}`:tr("真实场景参考，非该设施实拍")}</span><button data-action="facility-photos">${tr("照片与来源 {p0}", {p0:(icon('arrow-up-right'))})}</button></figcaption></figure>`}
function photoModal(){const c=facility(),g=photoGallery(c);return `<div class="sheet-top"><h2>${tr("照片与来源")}</h2><button class="icon-button" data-action="close-modal" aria-label="${tr("关闭照片")}">${icon('x')}</button></div><p>${esc(c.name)}</p>${g.matched?`<div class="photo-reference-note">${tr("以下为该地点的历史实拍照片，建筑现状与当天开放情况请以现场为准。")}</div>`:`<div class="photo-reference-note">${tr("本设施的实景照片尚未核实。下面展示的是同类公共空间的真实照片，仅作场景参考，并非本设施实拍。")}</div>`}${g.items.map((p,i)=>`<figure style="margin:0"><div class="photo-viewer"><img src="${p.src}" alt="${esc(p.caption)}" decoding="async" ${i?'loading="lazy"':''}></div><figcaption class="photo-attribution"><strong>${esc(p.caption)}</strong><p>${tr("摄影：{p0}{p1}", {p0:(esc(p.author)), p1:(p.year?' · '+p.year:'')})}<br>${tr("授权：{p0}", {p0:(esc(p.license))})}<br>${esc(p.changes)}</p><div class="photo-source-links"><a href="${esc(p.source)}" target="_blank" rel="noopener noreferrer">${tr("查看原始来源 ↗")}</a>${p.licenseUrl?`<a href="${esc(p.licenseUrl)}" target="_blank" rel="noopener noreferrer">${tr("授权说明 ↗")}</a>`:''}</div></figcaption></figure>`).join('')}`}
function facilityPage(){const c=facility(),saved=S.favorites.includes(favoriteKey());return `${back()}${facilityPhoto(c)}<div class="page-top mt"><div><div class="eyebrow">${CITY_NAMES[S.city]} · ${c.type==='library'?tr("公共图书馆"):tr("公共设施")}</div><h1 style="font-size:27px">${esc(c.name)}</h1></div><button class="icon-button" data-action="favorite" aria-label="${saved?tr("取消收藏"):tr("收藏设施")}" aria-pressed="${saved}">${icon(saved?'bookmark-check':'bookmark')}</button></div><span class="pill">${tr("开放状态待核验")}</span><div class="card mt"><dl class="detail-grid"><div><dt>${tr("记录开放时间")}</dt><dd>${esc(formatHours(c.hours))}</dd></div><div><dt>${tr("标称接待容量")}</dt><dd>${tr("{p0} 人", {p0:(c.capacity)})}</dd></div><div><dt>${tr("供电配置")}</dt><dd>${c.has_power?tr("有"):tr("待确认")}</dd></div><div><dt>${tr("无障碍服务")}</dt><dd>${tr("待核验")}</dd></div></dl></div>${section(tr("位置"))}<div class="card soft"><div class="row">${icon('map-pin')}<span style="font-size:13px">${c.lat.toFixed(4)}, ${c.lon.toFixed(4)}</span></div><p class="mt-sm" style="font-size:12px">${tr("详细街道地址与联系电话尚未收录。")}</p></div><div class="page-bottom-action">${btn(tr("查看地图位置"),'directions','primary wide','','navigation')}${btn(saved?tr("已收藏"):tr("收藏这个避暑点"),'favorite','wide mt-sm',`aria-pressed="${saved}"`,saved?'bookmark-check':'bookmark')}</div>${note(tr("地图位置可查看，实时开放状态待核验"))}`}
function forecast(){return `${back()}${title(tr("未来 72 小时"),`${tr("{p0} · 高温情景预报", {p0:(CITY_NAMES[S.city])})}`)}<div class="chips">${[24,48,72].map(h=>`<button class="chip ${S.horizon===h?'selected':''}" data-action="horizon" data-value="${h}">${tr("+{p0} 小时", {p0:(h)})}</button>`).join('')}</div><div class="hero mt"><div class="between"><span class="label">${tr("+{p0} 小时 · 示例温度", {p0:(S.horizon)})}</span><span class="pill risk">${tr("高温情景")}</span></div><div class="hero-main"><span class="temperature">${temp(S.horizon)}<small>°C</small></span>${weatherArt()}</div><div class="hero-footer"><span>${tr("示例热浪概率 {p0}%", {p0:(S.horizon===48?'76':S.horizon===72?'62':'68')})}</span></div></div>${section(tr("预测时段"))}<div class="three">${[24,48,72].map(h=>`<button class="forecast-card" data-action="horizon" data-value="${h}"><span class="caption">${tr("+{p0} 小时", {p0:(h)})}</span>${icon(h===48?'sun':'cloud-sun')}<strong>${temp(h)}°</strong><span class="caption">${tr("固定示例")}</span></button>`).join('')}</div>${btn(tr("在地图上查看"),'forecast-map','primary wide mt','','map')}${section(tr("关于这份预报"))}<p>${tr("这里展示 24、48、72 小时的预测结构。当前温度与热浪概率为固定高温场景，不代表实时天气。")}</p>${note()}`}
function alerts(){const n=neighborhoods().slice().sort((a,b)=>b.risk-a.risk)[0];return `${title(tr("预警与提醒"),tr("留意你关心的城市与社区"),`<button class="icon-button" aria-label="${tr("提醒设置")}" data-action="go" data-page="subscriptions">${icon('sliders-horizontal')}</button>`)}<div class="chips">${[['community',tr("社区提醒")],['official',tr("官方预警")]].map(([id,t])=>`<button class="chip ${S.tab===id?'selected':''}" data-action="alert-tab" data-value="${id}">${t}</button>`).join('')}</div>${S.tab==='community'?`<div class="info-strip mt">${icon('heart-handshake')}<span>${tr("已关注 {p0} 个社区。{p1}", {p0:(S.followed.length), p1:(S.notifications?tr("提醒偏好已开启。"):tr("提醒偏好已关闭。"))})}</span></div><button class="card card-link mt ${S.read?'':'unread-card'}" data-action="open-alert"><div class="between"><span class="row"><span class="alert-icon">${icon('sun')}</span><span class="caption">${tr("{p0} · 示例提醒", {p0:(CITY_NAMES[S.city])})}</span></span>${S.read?`<span class="caption">${tr("已读")}</span>`:`<span class="read-indicator" aria-label="${tr("未读")}"></span>`}</div><h3 class="mt-sm">${esc(n.name)}<br>${tr("留意高温风险")}</h3><p class="mt-sm">${tr("了解影响时段，提前查看社区内的避暑资源。")}</p><div class="between mt-sm"><span class="caption">${tr("情景时间 10:00")}</span>${icon('arrow-up-right')}</div></button><div class="mt">${btn(tr("管理关注社区"),'go','wide','data-page="subscriptions"','plus')}</div>`:`<div class="card mt">${empty('cloud-off',tr("暂未连接官方预警"),tr("当前为离线展示，没有拉取 NWS 的实时警报。你仍可查看社区风险基线。"),btn(tr("查看社区风险"),'go','primary','data-page="map"'))}</div>`}${note(tr("本页为情景提醒，不代表正在生效的官方预警"))}`}
function alertPage(){return `${back()}<div class="eyebrow">${tr("{p0} {p1} · 社区提醒", {p0:(icon('bell')), p1:(CITY_NAMES[S.city])})}</div>${title(`${esc(hood().name)}<br>${tr("高温风险提醒")}`,tr("示例场景 · 非实时警报"))}<div class="card"><dl class="detail-grid"><div><dt>${tr("情景影响时段")}</dt><dd>${formatHours('12:00-17:00')}</dd></div><div><dt>${tr("时间基准")}</dt><dd>${tr("城市当地时间")}</dd></div><div><dt>${tr("来源")}</dt><dd>${tr("示例场景")}</dd></div><div><dt>${tr("提醒状态")}</dt><dd>${S.read?tr("已读"):tr("未读")}</dd></div></dl></div>${section(tr("接下来可以做什么"))}<div class="list">${row(tr("查看受影响社区"),tr("了解人口、环境与风险因素"),'go','data-page="community"','map-pin')}${row(tr("寻找避暑资源"),tr("确认设施位置与开放信息"),'go','data-page="resources"','landmark')}</div>${btn(S.read?tr("已标记为已读"):tr("标记为已读"),'read','wide mt',S.read?'disabled':'','check')}${note()}`}
function empty(g,t,p,b=''){return `<div class="empty"><span class="empty-icon">${icon(g)}</span><h2>${t}</h2><p>${p}</p>${b}</div>`}
function analysis(){const ns=neighborhoods().slice().sort((a,b)=>b.risk-a.risk);return `${back()}${title(tr("看懂热脆弱性"),tr("社区风险背后的环境与人口因素"))}<div class="chips">${[['social',tr("社区分析")],['genetic',tr("遗传研究")]].map(([id,t])=>`<button class="chip ${S.analysis===id?'selected':''}" data-action="analysis" data-value="${id}">${t}</button>`).join('')}</div>${S.analysis==='social'?`<div class="info-strip mt">${icon('chart-no-axes-combined')}<span>${tr("以下为项目社区风险基线排名，综合指数 CHVI 待单独接入。")}</span></div><div class="list mt">${ns.map((n,i)=>`<button class="list-row" data-action="hood" data-id="${n.idx}"><span class="row"><span class="number-circle">${i+1}</span><span><strong>${esc(n.name)}</strong><small>${tr("树冠 {p0}% · 空调 {p1}%", {p0:((n.pct_tree_canopy*100).toFixed(0)), p1:((n.pct_ac_access*100).toFixed(0))})}</small></span></span>${badge(n.risk)}</button>`).join('')}</div>`:`<div class="info-strip mt">${icon('flask-conical')}<span>${tr("探索性研究，还不能作为个人或人类社区健康预测的有效证据。")}</span></div>${section(tr("热耐受遗传指标 HTGS"))}<p>${tr("保留 6 个 SNP 标记与 5 个人群分组的研究结构。频率、效应值与人类关联证据仍需逐项核验。")}</p><div class="card mt"><span class="caption">${tr("涉及基因")}</span><p class="mt-sm" style="color:var(--text)">HSP90AA1 · HSP70 · TRPM3<br>KDM6A · HSPA1L</p></div>${section(tr("综合脆弱性框架"))}<div class="stack">${[[tr("社会脆弱性"),tr("人口、收入与慢性病因素")],[tr("遗传指标"),tr("探索性热耐受研究")],[tr("环境脆弱性"),tr("绿地、空调与地表环境")]].map(([t,p])=>`<div class="card"><h3>${t}</h3><p class="mt-sm">${p}</p></div>`).join('')}</div>`}${note(tr("分析模块与指标边界 · 数据说明"))}`}
function compare(){return `${back()}${title(tr("五座城市，一起关注"),tr("81 个社区 · 46 处避暑设施"))}<div class="list"><div class="compare-row comparison-head"><span>${tr("城市")}</span><span>${tr("社区")}</span><span>${tr("避暑点")}</span></div>${DATA.cities.map(c=>`<button class="compare-row" data-action="compare-city" data-id="${c.id}"><span><strong>${CITY_NAMES[c.id]}</strong><small>${S.language==='en'?c.state:c.name}</small></span><span>${DATA.neighborhoods.filter(n=>n.city===c.id).length}</span><span>${DATA.cooling_centers.filter(n=>n.city===c.id).length} ↗</span></button>`).join('')}</div><p class="mt" style="font-size:13px">${tr("选择一个城市，即可查看当地社区和避暑资源。切换城市不会移除已有关注。")}</p>${note(tr("覆盖数量来自项目本地数据"))}`}
function subscriptions(){const chosen=neighborhoods().filter(n=>S.followed.includes(followKey(n)));return `${back()}${title(tr("关注我的社区"),tr("跨城市保存你关心的地点"))}<div class="list"><button class="setting" data-action="notification" aria-pressed="${S.notifications}">${icon('bell')}<span><strong>${tr("接收高温提醒")}</strong><small>${tr("保存提醒偏好，系统推送尚未接入")}</small></span><span class="switch ${S.notifications?'on':''}" aria-hidden="true"></span></button></div>${section(tr("已关注的地点"))}<div class="list">${S.followed.length?S.followed.map(k=>{const[id,name]=k.split('|');return row(esc(name),CITY_NAMES[id]||id,'unfollow',`data-key="${esc(k)}"`,'heart-handshake')}).join(''):empty('heart-handshake',tr("还没有关注社区"),tr("在下方选择一个社区，也可以切换城市后继续添加。"))}</div>${section(`${tr("{p0}的社区", {p0:(CITY_NAMES[S.city])})}`,`<button class="text-button" data-action="cities">${tr("切换城市{p0}", {p0:(icon('chevron-down'))})}</button>`)}<div class="list">${neighborhoods().map(n=>{const f=S.followed.includes(followKey(n));return `<button class="list-row" data-action="follow-index" data-id="${n.idx}" aria-pressed="${f}"><span><strong>${esc(n.name)}</strong><small>${tr("风险基线 {p0}", {p0:(n.risk)})}</small></span><span style="color:${f?'var(--brand)':'var(--sub)'}">${icon(f?'circle-check':'circle-plus')}</span></button>`}).join('')}</div>`}
function favorites(){const list=DATA.cooling_centers.filter(c=>S.favorites.includes(favoriteKey(c)));return `${back()}${title(tr("收藏的避暑点"),list.length?`${tr("{p0} 处已收藏设施", {p0:(list.length)})}`:tr("把常用的避暑点放在这里"))}<div class="stack">${list.length?list.map(c=>{const i=DATA.cooling_centers.filter(x=>x.city===c.city).findIndex(x=>x.name===c.name);return `<button class="facility" data-action="favorite-open" data-city="${c.city}" data-id="${i}"><span class="facility-icon">${icon('bookmark-check')}</span><span class="facility-info"><span class="caption">${CITY_NAMES[c.city]}</span><h3>${esc(c.name)}</h3><span class="caption">${formatHours(c.hours)}</span></span>${icon('chevron-right')}</button>`}).join(''):empty('bookmark',tr("收藏下一处清凉"),tr("进入避暑点详情，轻点收藏，下次就能更快找到。"),btn(tr("查找避暑点"),'go','primary','data-page="resources"'))}</div>`}
function setting(g,t,p,action,attrs='',extra=''){return `<button class="setting" data-action="${action}" ${attrs}>${icon(g)}<span><strong>${t}</strong>${p?`<small>${p}</small>`:''}</span>${extra||icon('chevron-right')}</button>`}
function profile(){return `<div class="profile-head"><span class="profile-avatar">${icon('shield-check')}</span><div><h1>${tr("你的防暑空间")}</h1><p>${tr("把关心的城市，放在心上。")}</p></div></div><div class="two"><button class="stat" data-action="go" data-page="subscriptions" style="text-align:left"><span class="caption">${tr("关注的社区")}</span><strong>${S.followed.length}<span class="caption"> ${tr("个")}</span></strong></button><button class="stat" data-action="go" data-page="favorites" style="text-align:left"><span class="caption">${tr("收藏的避暑点")}</span><strong>${S.favorites.length}<span class="caption"> ${tr("处")}</span></strong></button></div><div class="settings-group"><div class="list">${setting('map-pin',tr("当前城市"),CITY_NAMES[S.city],'cities')}${setting('heart-handshake',tr("关注社区与提醒"),tr("管理跨城关注地点"),'go','data-page="subscriptions"')}${setting('bookmark',tr("收藏的避暑点"),tr("快速查看常用设施"),'go','data-page="favorites"')}</div></div><div class="settings-group"><div class="list">${setting('settings-2',tr("偏好设置"),tr("语言、外观、提醒与启动体验"),'go','data-page="settings"')}${setting('building-2',tr("市政管理工作区"),tr("资源安排与任务流程演示"),'manager')}${setting('info',tr("关于 HeatShield"),tr("了解产品、数据与使用边界"),'go','data-page="about"')}</div></div><div class="brand-preview"><img src="${S.theme==='dark'?'assets/logo-white.svg':'assets/logo.svg'}" alt="HeatShield" style="width:180px"><span class="tiny" style="margin-top:10px">${tr("让每个社区，都有一处清凉。")}</span></div>`}
function settings(){return `${back()}${title(tr("偏好设置"),tr("按照你的习惯使用 HeatShield"))}<div class="list"><label class="setting language-setting" for="app-language">${icon('languages')}<span><strong>${tr("语言")}</strong><small>${tr("切换中文或英文，偏好会自动保存")}</small></span><select id="app-language" data-action="language-select" aria-label="${tr("选择语言")}"><option value="zh" lang="zh-CN" ${S.language==='zh'?'selected':''}>${window.HeatShieldI18n.names.zh}</option><option value="en" lang="en" ${S.language==='en'?'selected':''}>${window.HeatShieldI18n.names.en}</option></select></label>${setting(S.theme==='dark'?'moon':'sun',tr("深色外观"),S.theme==='dark'?tr("已开启"):tr("已关闭"),'theme','aria-pressed="'+(S.theme==='dark')+'"',`<span class="switch ${S.theme==='dark'?'on':''}" aria-hidden="true"></span>`)}${setting('sparkles',tr("动态效果"),S.motion?tr("品牌动效与页面过渡已开启"):tr("已关闭动态效果"),'motion','aria-pressed="'+S.motion+'"',`<span class="switch ${S.motion?'on':''}" aria-hidden="true"></span>`)}${setting('bell',tr("高温提醒偏好"),tr("系统推送尚未接入"),'notification','aria-pressed="'+S.notifications+'"',`<span class="switch ${S.notifications?'on':''}" aria-hidden="true"></span>`)}</div>${section(tr("数据与使用帮助"))}<div class="list">${setting('sparkles',tr("使用引导"),tr("重新了解 HeatShield 的功能"),'welcome')}${setting('refresh-cw',tr("更新城市数据"),tr("重新载入本地社区与设施数据"),'refresh-settings')}${setting('wifi-off',tr("数据与连接状态"),tr("查看更新来源及连接情况"),'connection')}</div>${section(tr("你的数据"))}<div class="info-strip">${icon('lock-keyhole')}<span>${tr("关注、收藏和外观偏好仅保存在当前浏览器中，不会上传到线上系统。")}</span></div>`}
function about(){return `${back()}${title(tr("关于 HeatShield"),tr("社区高温防护与避暑资源平台"))}<div class="brand-preview"><img src="${S.theme==='dark'?'assets/logo-white.svg':'assets/logo.svg'}" alt="HeatShield"></div><p class="mt">${tr("了解所在社区的高温风险，关注需要照顾的地方，更快找到身边的避暑资源。")}</p>${section(tr("数据覆盖"))}<div class="three"><div class="stat"><span class="caption">${tr("城市")}</span><strong>5</strong></div><div class="stat"><span class="caption">${tr("社区")}</span><strong>81</strong></div><div class="stat"><span class="caption">${tr("避暑点")}</span><strong>46</strong></div></div>${section(tr("本次展示的数据"))}<div class="card"><ul class="note-list"><li>${tr("社区、点位、开放时间和容量沿用项目记录，尚未逐条外部核验。")}</li><li>${tr("天气、预测和提醒为明确标注的固定示例，不代表实时气象或官方预警。")}</li><li>${tr("街道底图已连接 OpenStreetMap；社区与设施坐标沿用项目记录，尚未逐条核验。暂不提供道路路径规划。")}</li><li>${tr("设施照片使用真实摄影。已匹配地点展示历史实拍；未核实地点明确标注场景参考。每张照片可查看拍摄者、原始来源与授权。")}</li><li>${tr("调度与任务进度仅在当前浏览器中演示，不向真实系统下发车辆。")}</li><li>${tr("遗传模块保留探索性研究，不用于个人判断。")}</li></ul></div>${section(tr("产品标识"))}<div class="list">${row(tr("HeatShield 品牌标识"),tr("太阳、盾牌与两道降温横线"),'go','data-page="brand"','shield-check')}</div><p class="tiny mt">${tr("界面采用 Radix Sand 色阶、Lucide 图标和 shadcn/ui 风格的原生 HTML 组件。")}</p>`}
function brand(){return `${back()}${title('HeatShield',tr("为每个社区，留一处清凉"))}<div class="brand-preview"><img src="${S.theme==='dark'?'assets/logo-white.svg':'assets/logo.svg'}" alt="${tr("HeatShield 标志")}"></div><div class="brand-icon-preview"><img src="assets/icon.svg" alt="${tr("HeatShield App 图标")}"></div><p>${tr("以盾牌围住一轮太阳，两道横线代表降温与遮蔽。陶土橙用于产品识别，Sand 中性色承载日常界面。")}</p>${section(tr("可编辑矢量文件"))}<div class="stack"><a class="btn" href="assets/icon.svg" download="HeatShield-icon.svg">${tr("{p0}下载 App icon", {p0:(icon('download'))})}</a><a class="btn" href="assets/logo.svg" download="HeatShield-logo.svg">${tr("{p0}下载横版 logo", {p0:(icon('download'))})}</a><a class="btn" href="assets/logo-white.svg" download="HeatShield-logo-white.svg">${tr("{p0}下载浅色字标", {p0:(icon('download'))})}</a></div>`}
function dispatch(){if(!S.manager)return empty('lock-keyhole',tr("这是管理工作区"),tr("请从“我的”进入管理演示，不会获得真实系统权限。"),btn(tr("返回我的"),'go','primary','data-page="profile"'));return `${back()}${title(tr("城市资源调度"),`${tr("{p0} · 管理流程演示", {p0:(CITY_NAMES[S.city])})}`)}<div class="info-strip">${icon('info')}<span>${tr("方案与任务为本地演示，不向线上系统下发指令。")}</span></div><div class="two mt"><div class="stat"><span class="caption">${tr("社区数量")}</span><strong>${neighborhoods().length}</strong></div><div class="stat"><span class="caption">${tr("固定避暑设施")}</span><strong>${facilities().length}</strong></div></div>${section(tr("配置移动资源"))}<div class="card"><label class="form-field" style="margin:0">${tr("移动降温车数量")}<select id="units" ${S.busy?'disabled':''}>${[1,2,3,4,5].map(n=>`<option value="${n}" ${S.units===n?'selected':''}>${tr("{p0} 辆", {p0:(n)})}</option>`).join('')}</select></label><p class="tiny mt-sm">${tr("优先检查高风险社区与固定设施的覆盖缺口。")}</p></div>${btn(S.busy?tr("正在计算方案…"):S.plan?tr("重新生成示例方案"):tr("生成示例方案"),'generate','primary wide mt',S.busy?'disabled':'',S.busy?'':'route')}${S.busy?`<p class="loading-copy mt-sm"><span class="spinner"></span>${tr("正在整理社区与资源…")}</p>`:''}${S.plan&&!S.busy?`<div class="card mt"><div class="between"><h3>${tr("示例方案已准备好")}</h3><span class="pill">${tr("待确认")}</span></div><p class="mt-sm">${tr("{p0} 辆车 · {p1} 个示例停靠社区", {p0:(S.units), p1:(Math.min(S.units*2,neighborhoods().length))})}</p>${btn(tr("检查方案与任务"),'go','wide mt-sm','data-page="task"','arrow-right')}</div>`:''}${section(tr("固定设施"))}<div class="list">${row(tr("查看本城设施"),tr("核对开放时间、容量和服务条件"),'go','data-page="resources"','landmark')}</div>`}
function task(){if(!S.manager)return dispatch();if(!S.plan)return `${back()}${empty('route',tr("还没有调度方案"),tr("先设置车辆数量，生成一份示例方案。"),btn(tr("配置资源"),'go','primary','data-page="dispatch"'))}`;const stages=['draft','confirmed','active','complete'],s=stages.indexOf(S.taskStatus),labels={draft:tr("待确认"),confirmed:tr("已确认"),active:tr("执行中"),complete:tr("已完成")},stops=neighborhoods().slice().sort((a,b)=>b.risk-a.risk).slice(0,S.units*2);return `${back()}${title(tr("移动降温服务"),`${tr("{p0} · 本地演示任务", {p0:(CITY_NAMES[S.city])})}`,`<span class="pill">${labels[S.taskStatus]}</span>`)}<div class="card"><div class="between"><span class="caption">${tr("投入资源")}</span><strong style="font-weight:500">${tr("{p0} 辆车 / {p1} 站", {p0:(S.units), p1:(stops.length)})}</strong></div></div>${section(tr("示例服务顺序"))}<div class="card">${stops.map((n,i)=>`<div class="timeline-row ${s===3?'done':''}"><span class="timeline-dot">${s===3?icon('check'):i+1}</span><div><strong>${esc(n.name)}</strong><p>${tr("社区风险基线 {p0} · 到达时间待安排", {p0:(n.risk)})}</p></div></div>`).join('')}</div>${S.taskStatus==='complete'?`<div class="check-mark">${icon('check')}</div><p style="text-align:center">${tr("示例任务已完成")}</p>`:btn(S.busy?tr("处理中…"):S.taskStatus==='draft'?tr("确认示例方案"):S.taskStatus==='confirmed'?tr("开始模拟执行"):tr("完成模拟任务"),'task-next','primary wide mt',S.busy?'disabled':'',S.busy?'':'check')}${S.taskStatus==='draft'?btn(tr("返回修改资源"),'go','wide mt-sm','data-page="dispatch"'):''}<p class="tiny mt">${tr("此处只演示确认与执行流程，不代表真实服务已发生。")}</p>`}
function welcomeArt(){return window.HEATSHIELD_ART?.launch||`<img src="assets/launch-art.svg" width="340" height="320" alt="${tr("暖金色太阳下，一面盾牌带来清凉与保护")}">`}
function welcome(){return `<main class="onboard launch-welcome"><div class="launch-top"><div class="wordmark"><img src="assets/icon.svg" alt="">HeatShield</div><div class="launch-options"><button class="language-shortcut" data-action="language-toggle" aria-label="${tr("切换界面语言")}">${icon('languages')}${S.language==='en'?window.HeatShieldI18n.names.zh:window.HeatShieldI18n.names.en}</button><button class="motion-toggle" data-action="motion" aria-label="${S.motion?tr("暂停动效"):tr("开启动效")}" aria-pressed="${!S.motion}">${icon(S.motion?'pause':'play')}<span>${S.motion?tr("暂停动效"):tr("开启动效")}</span></button></div></div><div class="onboard-art"><button class="launch-art-button" data-action="replay-art" aria-label="${tr("重播太阳与盾牌动效")}"><span class="art-tap-ring" aria-hidden="true"></span><span class="launch-visual" role="img" aria-label="${tr("太阳缓缓升起，盾牌为城市带来清凉")}">${welcomeArt()}</span></button></div><div class="launch-intro"><div class="launch-kicker">${tr("城市高温 · 社区守护")}</div><h1>${tr("为炎热的城市，")}<br>${tr("留一处清凉。")}</h1><p>${tr("看见社区的高温风险，")}<br>${tr("找到你和家人身边的避暑去处。")}</p></div><div class="onboard-bottom"><button class="launch-city" data-action="go" data-page="choose" aria-label="${tr("当前城市{p0}，切换城市", {p0:(CITY_NAMES[S.city])})}"><span>${icon('map-pin')}${CITY_NAMES[S.city]}</span><span>${tr("切换城市 {p0}", {p0:(icon('chevron-right'))})}</span></button>${btn(tr("开始使用"),'launch-app','primary wide','','arrow-right')}<p class="launch-footnote">${tr("5 座城市相连，为每一个社区着想。")}</p></div></main>`}
function cityChoices(action='select-city'){return DATA.cities.map(c=>`<button class="city-choice ${S.city===c.id?'selected':''}" data-action="${action}" data-id="${c.id}" aria-pressed="${S.city===c.id}"><span class="city-glyph">${icon(c.id==='nyc'?'building-2':c.id==='miami'?'waves':'landmark')}</span><span><strong>${CITY_NAMES[c.id]}</strong><small>${tr("{p0} · {p1} 社区", {p0:(S.language==='en'?c.state:c.name), p1:(DATA.neighborhoods.filter(n=>n.city===c.id).length)})}</small></span>${icon(S.city===c.id?'circle-check':'chevron-right')}</button>`).join('')}
function launchScreen(){return `<main class="launch-loading" aria-busy="true" aria-label="${tr("HeatShield 正在加载")}"><div class="launch-loading-core"><div class="launch-emblem"><span></span><span></span><img src="assets/icon.svg" width="80" height="80" alt=""></div><h1>HeatShield</h1><p>${tr("让每个社区，都有一处清凉。")}</p><div class="launch-load-panel"><div class="launch-load-city">${icon('map-pin')}${CITY_NAMES[S.city]}</div><div class="launch-progress" role="progressbar" aria-label="${tr("城市资料准备进度")}" aria-valuemin="0" aria-valuemax="3" aria-valuenow="0"><span id="launch-progress-fill"></span></div><div id="launch-status" role="status" aria-live="polite">${tr("正在准备城市资料…")}</div><div class="launch-steps" aria-hidden="true"><span class="current">${tr("社区风险")}</span><i></i><span>${tr("避暑资源")}</span><i></i><span>${tr("准备就绪")}</span></div></div></div><div class="launch-loading-footer">HEATSHIELD <span>${tr("以清凉，守护日常。")}</span></div></main>`}
async function launchApp(){if(S.busy)return;const token=++loadToken;S.busy=true;S.launching=true;S.welcomed=true;save();render({animate:true});requestAnimationFrame(()=>preparePhotoAssets());const stages=[{delay:450,label:tr("社区资料已就绪"),value:1},{delay:450,label:tr("附近的避暑资源已就绪"),value:2},{delay:450,label:tr("准备好了，一起出发。"),value:3}];for(const stage of stages){await new Promise(r=>setTimeout(r,stage.delay));if(token!==loadToken)return;const progress=$('.launch-progress');if(!progress)return;progress.setAttribute('aria-valuenow',String(stage.value));$('#launch-progress-fill').style.width=(stage.value/3*100)+'%';$('#launch-status').textContent=stage.label;document.querySelectorAll('.launch-steps span').forEach((el,i)=>el.classList.toggle('current',i<stage.value))}await new Promise(r=>setTimeout(r,250));if(token!==loadToken)return;S.busy=false;S.launching=false;go('home',{replace:true})}
function choose(){return `<main class="onboard"><div class="wordmark"><img src="assets/icon.svg" alt="">HeatShield</div><button class="back-button" data-action="go" data-page="welcome">${tr("{p0}返回", {p0:(icon('arrow-left'))})}</button><div class="eyebrow">${tr("开始关注你的城市")}</div><h1 style="font-size:29px">${tr("你想先了解哪里？")}</h1><p>${tr("选择城市后，你随时可以切换，")}<br>${tr("也可以关注其他城市的社区。")}</p><div class="city-list">${cityChoices('onboard-city')}</div><div class="onboard-bottom">${btn(`${tr("进入{p0}", {p0:(CITY_NAMES[S.city])})}`,'finish-onboard','primary wide','','arrow-right')}<p class="tiny" style="text-align:center;margin-top:13px">${tr("不需要提供定位权限。")}</p></div></main>`}
function skeleton(){return `<div class="loading-copy" role="status"><span class="spinner"></span>${tr("正在整理{p0}的信息…", {p0:(CITY_NAMES[S.city])})}</div><div class="skeleton skeleton-title"></div><div class="skeleton skeleton-line" style="width:40%"></div><div class="home-grid mt"><div><div class="skeleton skeleton-hero"></div><div class="two mt-sm"><div class="skeleton skeleton-block"></div><div class="skeleton skeleton-block"></div></div></div><div class="stack"><div class="skeleton skeleton-block"></div><div class="skeleton skeleton-block"></div><div class="skeleton skeleton-block"></div></div></div>`}
function activeNav(){if(['community','map'].includes(S.page))return'map';if(['resources','facility','favorites','dispatch','task'].includes(S.page))return'resources';if(['alerts','alert'].includes(S.page))return'alerts';if(['profile','settings','subscriptions','about','brand'].includes(S.page))return'profile';return'home'}
function mainHeader(){return `<header class="app-header"><div class="container header-inner"><button class="wordmark" data-action="go" data-page="home" aria-label="${tr("HeatShield 首页")}"><img src="assets/icon.svg" alt="">HeatShield</button><div class="header-actions"><button class="city-button" data-action="cities" aria-label="${tr("切换城市，当前{p0}", {p0:(CITY_NAMES[S.city])})}">${icon('map-pin')}${CITY_NAMES[S.city]}${icon('chevron-down')}</button><button class="icon-button ${S.read?'':'bell-dot'}" aria-label="${tr("查看预警")}" data-action="go" data-page="alerts">${icon('bell')}</button></div></div></header>`}
function nav(){return `<nav class="bottom-nav" aria-label="${tr("主导航")}"><div class="bottom-nav-inner">${[['home','house',tr("首页")],['map','map',tr("地图")],['resources','landmark',tr("避暑")],['alerts','bell',tr("提醒")],['profile','user-round',tr("我的")]].map(([page,g,t])=>`<button class="nav-item ${activeNav()===page?'active':''}" data-action="go" data-page="${page}" aria-current="${activeNav()===page?'page':'false'}">${icon(g)}<span>${t}</span></button>`).join('')}</div></nav>`}
const pages={home,map,resources,alerts,profile,community,facility:facilityPage,forecast,analysis,compare,subscriptions,favorites,settings,about,brand,dispatch,task,alert:alertPage};
function motionEnabled(){return S.motion&&!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches}
function preparePhotoAssets(){if(photosPrepared)return;photosPrepared=true;if(typeof URL?.createObjectURL!=='function')return;for(const p of Object.values(PHOTOS.assets)){if(!p.src.startsWith('data:image/jpeg;base64,'))continue;try{const raw=atob(p.src.slice(p.src.indexOf(',')+1));const bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));p.src=URL.createObjectURL(new Blob([bytes],{type:'image/jpeg'}))}catch{}}}
function replayArt(){if(!motionEnabled())return;const art=$('.launch-art-button');if(!art)return;art.classList.remove('art-tapped');requestAnimationFrame(()=>{art.classList.add('art-tapped');setTimeout(()=>art.classList.remove('art-tapped'),750)})}
function changeLanguage(language){
  if(!['zh','en'].includes(language)||language===S.language)return;
  if(S.modal)closeModal(false);
  S.language=language;window.HeatShieldI18n.setLanguage(language);save();render({preserve:true});
}
function applyTheme(){document.documentElement.lang=S.language==='en'?'en':'zh-CN';document.documentElement.dataset.language=S.language;document.querySelector('meta[name="description"]')?.setAttribute('content',tr("HeatShield，了解社区高温风险，找到身边的避暑资源。"));document.documentElement.dataset.motion=motionEnabled()?'full':'reduced';document.documentElement.classList.toggle('dark',S.theme==='dark');$('meta[name="theme-color"]')?.setAttribute('content',S.theme==='dark'?'#111110':'#fdfdfc')}
function render({preserve=false,scroll=null,animate=false}={}){const y=scroll??(preserve?window.scrollY:0),active=preserve?document.activeElement:null,focusKey=active?.dataset?.action?{...active.dataset}:null;disposeLiveMap();window.HeatShieldRisk3D?.dispose();applyTheme();const app=$('#app');app.dataset.page=S.launching?'loading':S.page;app.dataset.enter=String(animate&&!preserve);if(S.launching){app.innerHTML=launchScreen()}else if(['welcome','choose'].includes(S.page)){app.innerHTML=(S.page==='welcome'?welcome:choose)()}else{app.innerHTML=mainHeader()+`<main id="main-content" class="container"><div class="page ${['home','map','resources'].includes(S.page)?'':'narrow'} ${animate?'':'no-motion'}" ${S.loading?'aria-busy="true"':''}>${S.loading?skeleton():(pages[S.page]||home)()}</div></main>`+nav()}document.title='HeatShield';window.parent!==window&&window.parent.postMessage({type:'heatshield-language',language:S.language},location.origin==='null'?'*':location.origin);icons();renderedPage=S.page;mountLiveMap();if(S.page==='map'&&S.layer==='3d'&&!S.loading)window.HeatShieldRisk3D.mount({cityId:S.city,neighborhoods:neighborhoods(),facilities:facilities(),cooling:S.cooling,onCommunity:id=>{S.hood=id;go('community')},onFacility:id=>{S.facility=id;go('facility')}});requestAnimationFrame(()=>{window.scrollTo({top:y,behavior:'instant'});if(focusKey){const replacement=[...app.querySelectorAll('[data-action]')].find(el=>Object.entries(focusKey).every(([k,v])=>el.dataset[k]===v));replacement?.focus({preventScroll:true})}})}
function snapshot(){return {page:S.page,city:S.city,hood:S.hood,facility:S.facility,scroll:window.scrollY,depth:S.depth}}
function go(page,{replace=false,load=false}={}){if(page==='alert'){}else if(!ROUTES.includes(page))page='home';if(S.modal)closeModal(false);if(S.busy){toast(tr("请等待当前操作完成"));return}if(page===S.page&&!load){window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return}history.replaceState(snapshot(),'',location.href);$('#app').dataset.direction=['home','map','resources','alerts','profile'].includes(page)?'tab':'forward';if(page!=='map')S.mapExplore=false;S.page=page;++loadToken;if(!replace)S.depth++;if(replace)history.replaceState({...snapshot(),scroll:0},'','#'+page);else history.pushState({...snapshot(),scroll:0},'','#'+page);if(load)loadPage();else{S.loading=false;render({animate:true})}}
function backPage(){if((history.state?.depth||0)>0&&S.page!=='home'){history.back()}else go(activeNav(),{replace:true})}
async function loadPage(){const token=++loadToken;S.loading=true;render({animate:true});await new Promise(r=>setTimeout(r,320));if(token!==loadToken)return;S.loading=false;render()}
function toast(t){const el=$('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600)}
function toggleFollow(idx=S.hood){const key=followKey(neighborhoods()[idx]),had=S.followed.includes(key);S.followed=had?S.followed.filter(x=>x!==key):[...S.followed,key];save();render({preserve:true});toast(had?tr("已取消关注"):tr("已关注这个社区"))}
function switchCity(id,{page=null}={}){if(!DATA.cities.some(c=>c.id===id))return;const changed=id!==S.city;if(S.modal)closeModal(false);if(!changed&&!page){render({preserve:true});return}S.city=id;S.busy=false;S.hood=0;S.facility=0;S.plan=false;S.taskStatus='draft';S.filter='all';S.query='';if(page)S.page=page;else if(!['home','map','resources','alerts','profile','compare','subscriptions'].includes(S.page))S.page=activeNav();save();history.replaceState({...snapshot(),scroll:0},'','#'+S.page);loadPage()}
function modalContent(name){if(name==='map-source')return mapSourceModal();if(name==='photos')return photoModal();if(name==='cities')return `<div class="sheet-top"><h2>${tr("选择城市")}</h2><button class="icon-button" data-action="close-modal" aria-label="${tr("关闭面板")}">${icon('x')}</button></div><p>${tr("切换城市，关注的地点会继续保留。")}</p><div class="search-wrap">${icon('search')}<input id="city-search" placeholder="${tr("搜索城市或英文名称")}" aria-label="${tr("搜索城市")}"></div><div class="city-list" id="city-results">${cityChoices()}</div>`;if(name==='directions'){const c=facility(),url=`https://www.google.com/maps/search/?api=1&query=${c.lat}%2C${c.lon}`;return `<div class="sheet-top"><h2>${tr("查看地图位置")}</h2><button class="icon-button" data-action="close-modal" aria-label="${tr("关闭面板")}">${icon('x')}</button></div><div class="notice-card"><strong>${esc(c.name)}</strong><p>${CITY_NAMES[S.city]} · ${c.lat.toFixed(4)}, ${c.lon.toFixed(4)}</p></div><p>${tr("将在外部地图中查看该坐标。请再次核对设施名称、入口和当天开放情况。")}</p><a class="btn primary wide mt" href="${url}" target="_blank" rel="noreferrer" data-action="external-map">${tr("{p0}打开 Google Maps", {p0:(icon('external-link'))})}</a>${btn(tr("继续留在 HeatShield"),'close-modal','wide')}`};if(name==='manager')return `<div class="sheet-top"><h2>${tr("进入管理工作区")}</h2><button class="icon-button" data-action="close-modal" aria-label="${tr("关闭面板")}">${icon('x')}</button></div><div class="notice-card"><strong>${tr("了解城市降温资源如何安排")}</strong><p>${tr("可以设置移动降温车、检查示例方案与跟进任务。此展示不提供真实管理权限，也不会下发车辆。")}</p></div>${btn(tr("进入管理演示"),'manager-enter','primary wide','','arrow-right')}${btn(tr("暂不进入"),'close-modal','wide')}`;if(name==='confirm-task')return `<div class="sheet-top"><h2>${tr("确认这份示例方案？")}</h2><button class="icon-button" data-action="close-modal" aria-label="${tr("关闭面板")}">${icon('x')}</button></div><div class="notice-card"><strong>${tr("{p0} · {p1} 辆移动降温车", {p0:(CITY_NAMES[S.city]), p1:(S.units)})}</strong><p>${tr("请检查服务社区与资源配置。确认后仅生成本地任务状态，不会下发真实指令。")}</p></div>${btn(tr("确认示例方案"),'confirm-task','primary wide','','check')}${btn(tr("返回继续检查"),'close-modal','wide')}`;if(name==='connection')return `<div class="sheet-top"><h2>${tr("连接状态")}</h2><button class="icon-button" data-action="close-modal" aria-label="${tr("关闭面板")}">${icon('x')}</button></div>${empty('wifi-off',tr("暂时无法获取在线更新"),tr("你仍可以查看本地社区与避暑点数据。关注和收藏不会丢失。"),btn(tr("重新加载本地数据"),'retry','primary'))}<p class="tiny">${tr("本展示使用本地数据快照，尚未接入实时更新。")}</p>`;return ''}
function openModal(name,trigger=null){clearTimeout(modalCloseTimer);if(S.modal)closeModal(false);S.modal=name;modalTrigger=trigger||document.activeElement;S.modalScroll=window.scrollY;const shell=$('#app');shell.setAttribute('inert','');document.body.style.position='fixed';document.body.style.top=-S.modalScroll+'px';document.body.style.paddingRight=(innerWidth-document.documentElement.clientWidth)+'px';document.body.style.width='100%';document.body.classList.add('modal-open');$('#modal-root').innerHTML=`<div class="modal-backdrop" data-backdrop="true"><section class="sheet" role="dialog" aria-modal="true" aria-label="${name==='map-source'?tr("地图与数据"):name==='photos'?tr("照片与来源"):name==='cities'?tr("选择城市"):name==='confirm-task'?tr("确认示例方案"):tr("操作面板")}"><div class="sheet-handle"></div>${modalContent(name)}</section></div>`;icons();requestAnimationFrame(()=>$('#modal-root button')?.focus({preventScroll:true}))}
function finishCloseModal(restore=true){clearTimeout(modalCloseTimer);if(!S.modal)return;const y=S.modalScroll;S.modal=null;$('#modal-root').innerHTML='';$('#app').removeAttribute('inert');document.body.style.position='';document.body.style.top='';document.body.style.width='';document.body.style.paddingRight='';document.body.classList.remove('modal-open');window.scrollTo({top:y,behavior:'instant'});if(restore&&modalTrigger?.isConnected)modalTrigger.focus({preventScroll:true})}
function closeModal(restore=true){if(!S.modal)return;const backdrop=$('#modal-root .modal-backdrop');if(restore&&motionEnabled()&&backdrop){if(backdrop.classList.contains('is-closing'))return;backdrop.classList.add('is-closing');modalCloseTimer=setTimeout(()=>finishCloseModal(restore),170);return}finishCloseModal(restore)}
function filterCities(value){const q=value.trim().toLowerCase();const nodes=[...document.querySelectorAll('#city-results .city-choice')];let shown=0;nodes.forEach(n=>{const aliases={phoenix:'凤凰城 phoenix',nyc:'纽约 new york nyc',houston:'休斯敦 houston',las_vegas:'拉斯维加斯 las vegas',miami:'迈阿密 miami'};const yes=(n.textContent+' '+(aliases[n.dataset.id]||'')).toLowerCase().includes(q);n.hidden=!yes;n.style.display=yes?'':'none';if(yes)shown++});$('#city-results .search-empty')?.remove();if(!shown){const el=document.createElement('p');el.className='search-empty tiny';el.textContent=tr("没有找到这个城市，试试其他名称。");$('#city-results').append(el)}}
async function generate(){if(S.busy)return;S.busy=true;S.plan=false;const cityId=S.city;render({preserve:true});await new Promise(r=>setTimeout(r,650));if(S.city!==cityId){S.busy=false;return}S.plan=true;S.taskStatus='draft';S.busy=false;render({preserve:true});toast(tr("示例方案已准备好，请检查后确认"))}
async function taskNext(confirm=false){if(S.busy||!S.manager||!S.plan)return;if(S.taskStatus==='draft'&&!confirm){openModal('confirm-task');return}if(S.modal)closeModal(false);const opCity=S.city;S.busy=true;render({preserve:true});await new Promise(r=>setTimeout(r,360));if(S.city!==opCity||!S.plan){S.busy=false;return}S.taskStatus=S.taskStatus==='draft'?'confirmed':S.taskStatus==='confirmed'?'active':'complete';S.busy=false;render({preserve:true});toast(S.taskStatus==='confirmed'?tr("示例方案已确认"):S.taskStatus==='active'?tr("已开始模拟执行"):tr("示例任务已完成"))}
function initEvents(){document.addEventListener('click',e=>{if(e.target.matches('[data-backdrop]')){closeModal();return}const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action;switch(a){case'go':go(el.dataset.page);break;case'back':backPage();break;case'cities':openModal('cities',el);break;case'close-modal':closeModal();break;case'select-city':switchCity(el.dataset.id);break;case'onboard-city':S.city=el.dataset.id;S.hood=0;S.facility=0;S.plan=false;S.taskStatus='draft';save();render({preserve:true});break;case'launch-app':case'finish-onboard':launchApp();break;case'hood':S.hood=Number(el.dataset.id);go('community');break;case'facility':S.facility=Number(el.dataset.id);go('facility');break;case'facility-photos':openModal('photos',el);break;case'forecast':S.horizon=Number(el.dataset.horizon);go('forecast');break;case'horizon':S.horizon=Number(el.dataset.value);S.page==='map'?refreshLiveMap():render({preserve:true});break;case'layer':{const old=S.layer;S.layer=el.dataset.value;old==='3d'||S.layer==='3d'?render({preserve:true}):refreshLiveMap();break}case'cooling':S.cooling=!S.cooling;refreshLiveMap();break;case'map-explore':S.mapExplore=!S.mapExplore;updateMapExplore();break;case'map-recenter':liveMapFit();break;case'map-retry':retryLiveMap();break;case'map-source':openModal('map-source',el);break;case'filter':S.filter=el.dataset.value;render({preserve:true});break;case'clear-search':S.query='';$('#resource-search').value='';updateResourceResults();$('#resource-search').focus({preventScroll:true});break;case'clear-filter':S.query='';S.filter='all';render({preserve:true});break;case'follow':toggleFollow();break;case'follow-index':toggleFollow(Number(el.dataset.id));break;case'unfollow':S.followed=S.followed.filter(k=>k!==el.dataset.key);save();render({preserve:true});toast(tr("已取消关注"));break;case'favorite':{const k=favoriteKey(),had=S.favorites.includes(k);S.favorites=had?S.favorites.filter(x=>x!==k):[...S.favorites,k];save();render({preserve:true});toast(had?tr("已取消收藏"):tr("已收藏这个避暑点"));break}case'favorite-open':{S.city=el.dataset.city;S.facility=Number(el.dataset.id);S.hood=0;save();go('facility');break}case'compare-city':switchCity(el.dataset.id,{page:'home'});break;case'notification':S.notifications=!S.notifications;save();render({preserve:true});toast(S.notifications?tr("已开启提醒偏好"):tr("已关闭提醒偏好"));break;case'language-toggle':changeLanguage(S.language==='en'?'zh':'en');break;case'motion':S.motion=!S.motion;save();render({preserve:true});break;case'replay-art':replayArt();break;case'theme':S.theme=S.theme==='dark'?'light':'dark';save();render({preserve:true});break;case'analysis':S.analysis=el.dataset.value;render({preserve:true});break;case'alert-tab':S.tab=el.dataset.value;render({preserve:true});break;case'open-alert':S.hood=neighborhoods().reduce((best,n,i,arr)=>n.risk>arr[best].risk?i:best,0);go('alert');break;case'read':S.read=true;render({preserve:true});toast(tr("已标记为已读"));break;case'forecast-map':S.layer='temperature';go('map');break;case'directions':openModal('directions',el);break;case'external-map':closeModal();break;case'refresh':loadPage();break;case'refresh-settings':go('home',{load:true});break;case'welcome':go('welcome');break;case'connection':openModal('connection',el);break;case'retry':closeModal();go('home',{load:true});break;case'manager':openModal('manager',el);break;case'manager-enter':S.manager=true;closeModal(false);go('dispatch');break;case'generate':generate();break;case'task-next':taskNext();break;case'confirm-task':taskNext(true);break}});document.addEventListener('change',e=>{if(e.target.id==='app-language'){changeLanguage(e.target.value);return}if(e.target.id==='units'){S.units=Number(e.target.value);S.plan=false;S.taskStatus='draft';render({preserve:true})}});document.addEventListener('input',e=>{if(e.target.id==='resource-search'){S.query=e.target.value;updateResourceResults()}if(e.target.id==='city-search')filterCities(e.target.value)});document.addEventListener('keydown',e=>{if(S.modal&&e.key==='Escape'){e.preventDefault();closeModal();return}if(S.modal&&e.key==='Tab'){const els=[...document.querySelectorAll('#modal-root button:not(:disabled),#modal-root a[href],#modal-root input')].filter(x=>x.getClientRects().length);if(!els.length)return;const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}if((e.key==='Enter'||e.key===' ')&&e.target.matches('.map-point')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}});window.addEventListener('popstate',e=>{if(S.modal)closeModal(false);$('#app').dataset.direction='back';++loadToken;S.loading=false;S.launching=false;S.busy=false;const p=e.state?.page||location.hash.slice(1)||'home';S.page=ROUTES.includes(p)||p==='alert'?p:'home';S.depth=e.state?.depth||0;if(DATA.cities.some(c=>c.id===e.state?.city))S.city=e.state.city;S.hood=e.state?.hood||0;S.facility=e.state?.facility||0;render({scroll:e.state?.scroll||0,animate:true});save()})}
async function boot(){history.scrollRestoration='manual';applyTheme();initEvents();const route=location.hash.slice(1);if(route==='map'&&new URLSearchParams(location.search).get('layer')==='3d')S.layer='3d';const deepLink=S.welcomed&&(ROUTES.includes(route)||route==='alert')&&!['home','welcome','choose'].includes(route);S.page=deepLink?route:'welcome';history.replaceState({...snapshot(),scroll:0},'','#'+S.page);if(deepLink)preparePhotoAssets();render({animate:true});window.matchMedia?.('(prefers-reduced-motion: reduce)').addEventListener('change',()=>{applyTheme();if(!S.launching)render({preserve:true})});document.addEventListener('visibilitychange',()=>{document.documentElement.classList.toggle('app-inactive',document.hidden)})}
boot();
